 List<string> WrapLinesL(string text,int width,int size){var result=new List<string>();foreach(var paragraph in text.Split('\n')){string row="";foreach(var word in paragraph.Split(' ',StringSplitOptions.RemoveEmptyEntries)){string next=row.Length==0?word:row+" "+word;if(row.Length>0&&ui.Measure(next,size)>width){result.Add(row);row=word;}else row=next;}result.Add(row);}return result;}
 string TimeRemainingL(DateTime deadline){double seconds=(deadline-world.Now).TotalSeconds;if(seconds<=0)return "expired";var t=TimeSpan.FromSeconds(seconds);return t.TotalDays>=1?$"{(int)t.TotalDays}d {t.Hours}h":t.TotalHours>=1?$"{(int)t.TotalHours}h {t.Minutes}m":$"{t.Minutes}m {t.Seconds}s";}
 List<string> ObjectiveLinesL(Mission38 m)
 {
  var run=world.EnsureMissionL(m);var lines=new List<string>();if(m.ProfileM is {} profile){lines.Add(profile.Mode=="Retrieve"?(m.ObjectiveDone?"Recovered / ":"Pending / ")+"Collect "+profile.CargoName+"; hostiles are optional.":profile.Mode=="Task"?(m.ObjectiveDone?"Complete / ":"Pending / ")+profile.Task+" using the actual activity window.":profile.Mode=="Combat"?(m.ObjectiveDone?"Complete / ":"Pending / ")+"Secure the encounter.":profile.CargoName);if(profile.Collateral>0)lines.Add($"Collateral {m.CollateralHeldM:N0} CR held / returned on delivery.");}if(m.State is "Completed" or "Failed" or "Expired" or "Declined")lines.Add("Contract / "+m.State);
  if(m.Spec.Division==AgentDivision38.Distribution)lines.Add($"Deliver {m.Spec.Volume:0.##} m3 of mission freight to {LocationLabelL(m.Destination)}.");
  else if(m.Spec.Division==AgentDivision38.Mining)lines.Add($"Harvest {m.Spec.Resource}: {m.Harvested:0.##} / {m.Spec.Volume:0.##} m3.");
  else if(m.Definition==DemoWorld.RelayDefinitionL){lines.Add((run.Fired.Contains("commander")?"Complete / ":"Pending / ")+"Destroy the relay commander; escorts are optional.");lines.Add((run.Events.Contains("collect")?"Complete / ":"Pending / ")+"Recover the dispatch in pocket two.");}
  else if(m.ProfileM==null){lines.Add($"Pocket {m.Pocket+1} / {run.Definition.Pockets}  ·  wave {m.Wave+1} / {m.Spec.Waves.Length}");lines.Add(m.ObjectiveDone?"Encounter objective complete.":"Complete the current hostile group or special objective.");}
  if(m.Spec.Volume>0){lines.Add($"Mission cargo aboard {m.Cargo:0.##} m3 / local hangar {m.Hangars.GetValueOrDefault(world.StationKey44):0.##} m3");lines.Add($"Required at delivery {m.Spec.Volume:0.##} m3 / {LocationLabelL(m.Destination)}");if(m.Cargo+m.Hangars.Values.Sum()+.001f<m.Spec.Volume&&m.Harvested>=m.Spec.Volume)lines.Add("Missing cargo / recover your owned loss wreck or abandon the contract.");}
  if(m.State=="Accepted"){lines.Add("Deadline / "+TimeRemainingL(m.Expires));lines.Add("Time bonus / "+TimeRemainingL(m.BonusUntil));}
  return lines;
 }
